const { mkdtempSync, mkdirSync, writeFileSync, rmSync } = await import('node:fs');
const { tmpdir } = await import('node:os');
const { join } = await import('node:path');
const { execFileSync } = await import('node:child_process');
const temp = mkdtempSync(join(tmpdir(), 'koala-product-reviewer-edge2-'));
try {
  mkdirSync(join(temp, 'docs', 'story', 'actives'), { recursive: true });
  mkdirSync(join(temp, 'docs', 'requirements'), { recursive: true });
  writeFileSync(join(temp, 'koala.config.json'), JSON.stringify({ scanRoot: 'packages/main', testsDir: 'packages/main/tests', fixturesDir: 'packages/main/tests/fixtures', storyDir: 'docs/story/actives', requirementsDir: 'docs/requirements', storyPrefix: 'B' }, null, 2));
  const created = execFileSync('node', [join($root, 'packages/main/dist/cli.js'), '--root', temp, 'story_create', JSON.stringify({ name: 'pr-refactor', title: 'PR refactor', description: 'tmp', type: 'refactor', priority: 'low', checklist: [{ title: 'review lane', context: 'tmp context' }] })], { cwd: $root, encoding: 'utf8' });
  const storyId = (created.match(/B-[a-f0-9]+/) || [])[0];
  execFileSync('node', [join($root, 'packages/main/dist/cli.js'), '--root', temp, 'understanding_set', JSON.stringify({ storyId, task: '验证低风险 story 的产品验收提醒仍为 advisory', outcome: '事件链路已经打通，但用户仍看不出具体完成画面。', facts: ['tmp'], constraints: ['tmp'], unknowns: [], touchpoints: ['packages/main/src/handlers/story-review.ts'] })], { cwd: $root, encoding: 'utf8' });
  execFileSync('node', [join($root, 'packages/main/dist/cli.js'), '--root', temp, 'checklist_update', JSON.stringify({ storyId, itemId: 'CHK-001', testIntent: { happy: [{ desc: 'ok', type: 'cli_blackbox' }], edge: [{ desc: 'ok', type: 'cli_blackbox' }], adversarial: [{ desc: 'ok', type: 'cli_blackbox' }] }, agent: 'test-intent' })], { cwd: $root, encoding: 'utf8' });
  const raw = execFileSync('node', [join($root, 'packages/main/dist/cli.js'), '--root', temp, 'story_review', JSON.stringify({ storyId })], { cwd: $root, encoding: 'utf8' });
  const review = JSON.parse(raw.slice(raw.indexOf('{')));
  const weak = (review.issues || []).find((issue) => issue.type === 'weak_outcome_transcript');
  return { hasWeakOutcome: Boolean(weak), blockerCount: review.summary.blockerCount };
} finally { rmSync(temp, { recursive: true, force: true }); }

